import {visualSlot,configureVisuals,resetVisuals,mountVisuals,cleanVisuals} from './visual-ui.js';
import {createExamUI} from './exams-ui.js';
import {cleanExam,checkDeadline} from './exams-core.js';
import {cleanProfile,recordEvent} from './adaptive.js';
import {progressHTML} from './progress-ui.js';
import {createCardUI} from './cards-ui.js';
import {cleanSession,masteredCount,dueQuestions,weakQuestions} from './cards-core.js';
import {cleanMemory,updateReview} from './review.js';
function extraRefs(ids=[]){return ids.length?'<span class="supplement">Lưu ý biên soạn thêm (ngoài PDF): '+ids.map(id=>{let r=supplementarySources.find(r=>r.id===id);return '<a target="_blank" rel="noopener" href="'+r.url+'">'+r.title+'</a>'}).join(' · ')+'</span>':''}
import {workedHTML,solveCalc} from './math-ui.js';
import {lessons,questions,chapters,sources,sourceMeta,chapterLessons,supplementarySources} from './data.js';
import {exercises} from './exercises.js';
import {blank,rank,answer,gradeNumeric} from './core.js';
const $=s=>document.querySelector(s),key='konoha-network-v1';
let state=blank(),storageOK=true;try{let raw=localStorage.getItem(key);if(raw)state=validate(JSON.parse(raw))}catch{storageOK=false}
let view='home',selectedChapter=0,lessonId=null,filter=-1,calc='subnet',run=null,notebookMode='formulas',exerciseIndex=0;
function validate(x){if(x?.version!==1||!Array.isArray(x.done)||!x.records||typeof x.records!=='object'||Array.isArray(x.records)||!x.days||!Array.isArray(x.exams)||!x.settings)throw Error('Bản sao lưu không đúng định dạng.');let s=blank();s.done=[...new Set(x.done.filter(id=>lessons.some(l=>l.id===id)))];for(let q of questions){let r=x.records[q.id];if(r&&[r.attempts,r.correct,r.streak,r.due].every(Number.isFinite)&&r.attempts>=0&&r.correct>=0&&r.correct<=r.attempts&&r.streak>=0)s.records[q.id]={attempts:r.attempts,correct:r.correct,streak:r.streak,due:r.due,lastOK:r.lastOK===true}}for(let [k,v] of Object.entries(x.days))if(k.length<20&&Number.isInteger(v)&&v>=0)s.days[k]=v;s.exams=x.exams.filter(e=>Number.isFinite(e.score)&&e.score>=0&&e.score<=100&&typeof e.date==='string').slice(-100);for(let ex of exercises){let r=x.exerciseRecords?.[ex.id];if(r&&Number.isInteger(r.attempts)&&r.attempts>0&&Number.isInteger(r.correct)&&r.correct>=0&&r.correct<=r.attempts)s.exerciseRecords[ex.id]={attempts:r.attempts,correct:r.correct,lastOK:r.lastOK===true}}s.settings={motion:x.settings.motion===true,sound:x.settings.sound===true};s.memory=cleanMemory(x.memory,questions.map(q=>q.id));s.cardSession=cleanSession(x.cardSession);s.examSession=cleanExam(x.examSession);s.visuals=cleanVisuals(x.visuals);s.profile=cleanProfile(x.profile,questions.map(q=>q.id),lessons.map(l=>l.id));return s}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Không lưu được. Hãy xuất bản sao tiến độ.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
const src=(ch,p)=>`<a href="sources/${sources[ch]}#page=${p[0]}" target="_blank" rel="noopener">${sources[ch]} · trang PDF ${p[0]}–${p[1]}</a>`;
const count=ch=>lessons.filter(l=>l.ch===ch&&state.done.includes(l.id)).length;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'});
const wrong=()=>questions.filter(q=>state.records[q.id]&&!state.records[q.id].lastOK);
const due=()=>questions.filter(q=>!state.records[q.id]||state.records[q.id].due<=Date.now());
const mastered=()=>masteredCount(state);
function go(v){view=v;run=null;render();window.scrollTo(0,0)}
function village(){return `<svg class="landscape" viewBox="0 0 560 340" role="img" aria-label="Minh họa bản đồ Làng Lá với tháp chỉ huy, những mái nhà và đường mòn"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b4b9a6" opacity=".4"/></pattern></defs><rect width="560" height="340" fill="url(#dots)"/><circle cx="376" cy="130" r="95" fill="#ed702d" opacity=".13"/><path d="M20 220 110 92 158 155 218 56 310 166 358 106 515 237" fill="#d9dece"/><path d="m67 220 100-121 34 66 34-34 45 79 58-49 67 67" fill="#bac6ad"/><path d="M63 270q74-68 141-19t140 10 164-26" fill="none" stroke="#cbbda2" stroke-width="32"/><path d="M63 270q74-68 141-19t140 10 164-26" fill="none" stroke="#f6edd9" stroke-width="25"/><g stroke="#455b4b" stroke-width="3" fill="#e7e5d2"><path d="M242 247v-91h86v91z"/><path d="M229 158h113l-24-22h-64z" fill="#617763"/><path d="M252 134v-34h65v34z"/><path d="M240 101h88l-44-23z" fill="#e77b42"/><path d="M269 247v-34h27v34z" fill="#697861"/><path d="M256 173h11v17h-11zm45 0h11v17h-11z" fill="#89937a"/></g><circle cx="285" cy="117" r="10" fill="#e77b42"/><text x="285" y="122" text-anchor="middle" font-size="15" fill="#fff">忍</text><g fill="#eee7d4" stroke="#647561" stroke-width="2"><path d="M127 243v-45h62v45z"/><path d="m116 199 43-28 43 28z" fill="#cc8155"/><path d="M363 253v-47h69v47z"/><path d="m350 208 48-32 48 32z" fill="#6e8168"/><path d="M167 276v-33h49v33z"/><path d="m158 244 34-23 34 23z" fill="#6e8168"/></g><g fill="#7f9876"><path d="m75 232 16-45 16 45zm362 8 18-56 18 56zm-329 44 14-40 14 40zm348 2 15-44 15 44z"/></g><path d="M66 112h63m-43-8h53m280-30h77m-51 12h64" stroke="#c6cbbb" stroke-width="5" stroke-linecap="round"/><circle cx="470" cy="124" r="28" fill="none" stroke="#c77b53" stroke-width="1"/><text x="470" y="130" text-anchor="middle" fill="#c77b53" font-size="18">木ノ葉</text><text x="47" y="318" font-size="11" letter-spacing="3" fill="#7a826d">KONOHA • NETWORK ACADEMY</text></svg>`}
const nav=[['home','⌘','Bản đồ nhiệm vụ'],['cards','⚡','Học bằng thẻ'],['progress','◈','Hồ sơ kiến thức'],['practice','▧','Luyện tự chọn'],['exam','◎','Kỳ thi Chūnin'],['calc','▧','Bài tính'],['notebook','▤','Sổ nhẫn thuật'],['sources','▱','Tài liệu gốc'],['settings','⚙','Tùy chỉnh']];
function render(){resetVisuals();document.body.classList.toggle('animate',state.settings.motion);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="logo">葉</span><span>HỌC VIỆN MẠNG<br><small>Làng Lá · Naruto inspired</small></span></div><nav class="nav" aria-label="Điều hướng chính">${nav.map(([id,ic,t])=>`<button data-go="${id}" class="${view===id||(view==='chapter'||view==='lesson')&&id==='home'?'active':''}"><b>${ic}</b>${t}</button>`).join('')}</nav><div class="side-bottom"><span class="daily">Mỗi ngày, giỏi hơn một chút</span><strong>Con đường ninja của bạn</strong><p>${state.done.length}/${lessons.length} buổi luyện đã hoàn thành</p><div class="progress"><i style="width:${state.done.length/lessons.length*100}%"></i></div></div></aside><div class="content"><header class="topbar"><span>HỌC VIỆN / ${nav.find(n=>n[0]===view)?.[2]||'BUỔI LUYỆN'}</span><div class="status"><span>✦ ${mastered()} chủ đề vững</span><span class="rank">${rank(state,lessons.length)}</span><span class="avatar">忍</span></div></header><main class="main" id="main">${body()}</main></div></div>`;bind();bindExercise();cardUI.bind();examUI.bind();mountVisuals();if(!storageOK){let e=document.createElement('p');e.className='error';e.textContent='Trình duyệt chưa lưu được tiến độ. Hãy xuất bản sao trong Tùy chỉnh.';$('#main').prepend(e)}}
function body(){if(view==='cards')return cardUI.html();if(view==='exam')return examUI.html();if(view==='progress')return progressHTML(state);if(run)return quiz();return ({home,chapter,lesson,practice,exam,calc:calculator,notebook,sources:sourcePage,settings}[view]||home)()}
function legacyHome(){return `<section class="hero"><div><div class="eyebrow">Hành trình ninja · Mạng máy tính</div><h1>Mỗi kiến thức mới,<br>một bước <span style="color:var(--orange)">trưởng thành.</span></h1><p>Không cần học thuộc cả cuộn thư. Bắt đầu từ một ý nhỏ, luyện từng câu và xây nền tảng mạng thật vững.</p><div class="actions"><button class="primary" data-resume>Tiếp tục luyện tập <span>✦</span></button><button class="secondary" data-go="practice">Luyện nhanh 5 câu</button></div></div>${village()}</section><section class="stats" aria-label="Tiến độ"><div class="stat"><strong>${state.done.length}<small>/${lessons.length}</small></strong><span>Buổi luyện hoàn thành</span></div><div class="stat"><strong>${mastered()}<small>/${lessons.length}</small></strong><span>Chủ đề vững qua nhiều ngày</span></div><div class="stat"><strong>${state.days[today()]||0}<small>/5</small></strong><span>Câu luyện hôm nay</span></div><div class="stat"><strong>${state.exams.length?Math.max(...state.exams.map(e=>e.score))+'%':'—'}</strong><span>Điểm thi cao nhất</span></div></section><div class="section-title"><h2>Bản đồ nhiệm vụ</h2><small>4 vùng kiến thức · Tự chọn lộ trình</small></div><section class="map-grid">${chapters.map((c,i)=>`<button class="chapter" data-ch="${i}" style="--c:${c.color}"><div class="chapter-art"><span class="kanji">${c.icon}</span><span class="seal">${c.icon}</span></div><div class="chapter-body"><small>Chương ${i+1} / ${c.topic}</small><h3>${c.name}</h3><p>${c.desc}</p><div class="progress"><i style="width:${count(i)/chapterLessons(i).length*100}%"></i></div><div class="chapter-foot"><span>${count(i)}/${chapterLessons(i).length} buổi luyện</span><span>${Math.round(count(i)/chapterLessons(i).length*100)}%</span></div></div></button>`).join('')}</section><div class="bottom-grid"><section class="panel"><span class="daily">Nhiệm vụ hằng ngày</span><h2 style="margin:12px 0">5 câu hôm nay. Nhớ lâu ngày mai.</h2><p class="muted">Ưu tiên câu cần ôn và câu chưa thuộc. Mỗi lần luyện là một cơ hội hiểu thêm, kể cả khi chọn “Chưa biết”.</p><button class="primary" data-start="daily">Nhận nhiệm vụ</button></section><section class="panel dark"><small>Sổ nhẫn thuật</small><h2 style="margin:12px 0">Sai cũng là một bước tiến.</h2><p>${wrong().length} câu đang chờ bạn luyện lại. Công thức và kiến thức hay nhầm đã có trong sổ.</p><button class="secondary" data-go="notebook" style="color:var(--ink)">Mở sổ của tôi</button></section></div>${footer()}`}
function home(){return `<section class="hero"><div><div class="eyebrow">Học bằng thẻ · Mạng máy tính</div><h1>Một thẻ nhỏ.<br>Một bước <span style="color:var(--orange)">vững hơn.</span></h1><p>Học từ câu hỏi, tự nhớ rồi ôn lại đúng lúc. 10 thẻ mỗi lượt, từ kiến thức nền đến bài tính.</p><div class="actions"><button class="primary" data-card-resume>${state.cardSession&&!state.cardSession.finished?'Tiếp tục lượt đang học':'Học ngay'}</button><button class="secondary" data-card-config>Chọn kiểu luyện</button></div></div>${village()}</section>${cardUI.picker()}<div class="card-entry-grid"><button class="panel" data-card-start="learn"><h2>Học ngay</h2><p>10 thẻ trắc nghiệm xen tự nhớ.</p></button><button class="panel" data-card-start="due"><h2>Ôn thẻ đến hạn</h2><p>${dueQuestions(state,cardUI.chapter()).length} kiến thức đến lịch ôn.</p></button><button class="panel" data-card-start="wrong"><h2>Luyện câu sai</h2><p>${weakQuestions(state,cardUI.chapter()).length} kiến thức cần củng cố.</p></button><button class="panel" data-go="exam"><h2>Kiểm tra tổng hợp</h2><p>Kỳ thi Chūnin · Chọn phạm vi, số câu và thời gian.</p></button></div><section class="stats" style="margin-top:26px"><div class="stat"><strong>${mastered()}<small>/${lessons.length}</small></strong><span>Chủ đề vững qua nhiều ngày</span></div><div class="stat"><strong>${state.done.length}<small>/${lessons.length}</small></strong><span>Bài lý thuyết đã đọc</span></div><div class="stat"><strong>${state.days[today()]||0}</strong><span>Lần luyện hôm nay</span></div><div class="stat"><strong>${state.cardSession&&!state.cardSession.finished?state.cardSession.index+1:'—'}</strong><span>Vị trí lượt đang học</span></div></section><div class="actions" style="margin-top:24px"><button class="secondary" data-card-start="diagnostic">Đánh giá đầu vào ngắn</button><button class="secondary" data-go="progress">Hồ sơ kiến thức & lượt học tiếp</button></div><div class="section-title"><h2>Bản đồ kiến thức</h2><small>Lý thuyết, ví dụ và PDF theo trang</small></div><div class="lesson-list">${chapters.map((c,i)=>`<button class="lesson-row" data-ch="${i}"><div><small>Chương ${i+1}</small><strong>${c.name} · ${c.topic}</strong><small>${chapterLessons(i).length} bài · ${questions.filter(q=>q.ch===i).length} kiến thức hỏi đáp</small></div><span>${count(i)}/${chapterLessons(i).length}</span></button>`).join('')}</div>${footer()}`}
function footer(){return `<footer class="footer">Học từ 4 tài liệu Mạng máy tính của ThS. Nguyễn Thị Phương Thảo, ĐH Thủy Lợi. Ví dụ ninja là minh họa tự tạo, không thuộc bài giảng hay cốt truyện Naruto. Tiến độ lưu trên thiết bị này.</footer>`}
function chapter(){let c=chapters[selectedChapter];return `<button class="back" data-go="home">Về bản đồ</button><div class="eyebrow">Chương ${selectedChapter+1} · ${c.topic}</div><h1>${c.name}</h1><p class="muted">${chapterLessons(selectedChapter).length} buổi luyện ngắn · ${questions.filter(q=>q.ch===selectedChapter).length} câu · khoảng 3–5 phút/bài · học theo thứ tự hoặc tự chọn.</p><div class="lesson-list">${lessons.filter(l=>l.ch===selectedChapter).map((l,i)=>`<button class="lesson-row" data-lesson="${l.id}"><div><small>Buổi luyện ${i+1}</small><strong>${l.title}</strong><small>Đọc · hiểu · luyện ${questions.filter(q=>q.lesson===l.id).length} câu</small></div><span class="check">${state.done.includes(l.id)?'✓':'+'}</span></button>`).join('')}</div><div class="actions" style="margin-top:24px"><button class="primary" data-start="chapter">Luyện chương này</button><button class="secondary" data-start="chapter-exam">Kiểm tra chương · 10 câu</button></div>${footer()}`}
function lesson(){let l=lessons.find(l=>l.id===lessonId);return `<article class="reading"><button class="back" data-backchapter>Về ${chapters[l.ch].name}</button><div class="eyebrow">Buổi luyện · Chương ${l.ch+1} · 3–5 phút</div><h1>${l.title}</h1><p class="body">${l.body}</p><aside class="analogy"><small style="color:#9d5028">Minh họa Naruto tự tạo</small><p>${l.analogy}</p></aside>${visualSlot(questions.find(q=>q.lesson===l.id),{key:'lesson:'+l.id,deep:true,mode:'unknown'})}<h3>Ghi vào sổ nhẫn thuật</h3><div class="formula">${l.memory}</div><p class="source">${(l.refs||[l.pages]).map(p=>src(l.ch,p)).join(' · ')} · Nội dung được diễn giải cho người mới. PDF là tài liệu tùy chọn tại máy. ${extraRefs(l.supplementary)}</p><div class="actions"><button class="primary" data-complete>${state.done.includes(l.id)?'Đã học ✓ · Luyện lại':'Đánh dấu đã học & luyện câu hỏi'}</button><button class="secondary" data-nextlesson>Bài tiếp theo</button></div></article>`}
function practice(){return `<div class="eyebrow">Sân luyện · Không áp lực điểm số</div><h1>Luyện một câu, nhớ một ý.</h1><p class="muted">Phím 1–4 để chọn · Enter để sang câu tiếp · Có thể tạm dừng bất cứ lúc nào.</p><div class="filter">${[-1,0,1,2,3].map(i=>`<button class="pill ${filter===i?'active':''}" data-filter="${i}">${i<0?'Tất cả':`Chương ${i+1}`}</button>`).join('')}</div><div class="bottom-grid"><div class="panel"><h2>Nhiệm vụ hằng ngày</h2><p>5 câu, ưu tiên câu đến hạn ôn. Đúng sau 1, 2, 4… ngày giúp xây trí nhớ dài hạn.</p><button class="primary" data-start="daily">Bắt đầu 5 câu</button></div><div class="panel"><h2>Luyện lại câu sai</h2><p>${wrong().filter(q=>filter<0||q.ch===filter).length} câu cần củng cố trong bộ lọc này.</p><button class="secondary" data-start="wrong">Luyện câu sai</button></div></div><div class="panel" style="margin-top:20px"><h2>Tự do luyện nhẫn thuật</h2><p>Luyện toàn bộ câu trong vùng đã chọn, có gợi ý hai bước và giải thích ngay.</p><button class="secondary" data-start="all">Luyện toàn bộ</button></div>`}
function exam(){return `<div class="eyebrow">Kỳ thi Chūnin · Kiểm tra tổng hợp</div><h1>Sẵn sàng nhận nhiệm vụ lớn?</h1><div class="panel"><h2>20 câu · Cân bằng 4 chương</h2><p>Mỗi chương 5 câu. Làm từng câu, không xem đáp án hay gợi ý trong lúc thi. Mỗi chương có lý thuyết, tình huống và bài tính. Không giới hạn thời gian; “Chưa biết” được tính chưa đúng. Kết quả kèm giải thích sẽ xuất hiện khi hoàn thành.</p><button class="primary" data-start="exam">Bắt đầu kỳ thi</button></div><h2 style="margin-top:28px">Lịch sử kết quả</h2>${state.exams.length?`<div class="table-wrap"><table><tr><th>Thời điểm</th><th>Bài thi</th><th>Kết quả</th></tr>${state.exams.slice().reverse().map(e=>`<tr><td>${new Date(e.date).toLocaleString('vi-VN')}</td><td>${e.kind==='chapter-exam'?'Kiểm tra chương':'Tổng hợp'}</td><td>${e.score}%</td></tr>`).join('')}</table></div>`:'<p class="muted">Chưa có lượt thi. Bạn có thể luyện trước khi tham gia.</p>'}`}
function shuffled(a){let out=[...a];for(let i=out.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function start(mode){if(mode==='chapter-exam'){examUI.configure(selectedChapter);go('exam');return}let pool=questions.filter(q=>filter<0||q.ch===filter),isExam=mode.includes('exam');if(mode==='exam')pool=chapters.flatMap((_,ch)=>['theory','scenario','calculation'].flatMap((kind,i)=>shuffled(questions.filter(q=>q.ch===ch&&q.kind===kind)).slice(0,i===2?1:2)));else if(mode==='chapter'||mode==='chapter-exam')pool=shuffled(questions.filter(q=>q.ch===selectedChapter)).slice(0,mode==='chapter-exam'?10:Infinity);else if(mode==='lesson')pool=questions.filter(q=>q.lesson===lessonId);else if(mode==='wrong')pool=shuffled(pool.filter(q=>state.records[q.id]&&!state.records[q.id].lastOK));else if(mode==='daily')pool=shuffled(pool).sort((a,b)=>(state.records[a.id]?.due||0)-(state.records[b.id]?.due||0)).slice(0,5);else pool=shuffled(pool);if(!pool.length){toast('Chưa có câu sai trong bộ lọc này. Thử luyện hằng ngày nhé.');return}run={id:'practice-'+Date.now()+'-'+Math.random().toString(36).slice(2),mode,exam:isExam,pool:pool.map(q=>{let optionOrder=shuffled([0,1,2,3]);return {...q,optionOrder,options:optionOrder.map(i=>q.options[i]),correct:optionOrder.indexOf(q.correct)}}),index:0,selected:null,hints:0,answers:[],finished:false};render();window.scrollTo(0,0)}
function quiz(){if(run.finished)return results();let q=run.pool[run.index],answered=run.selected!==null;return `<div class="quiz-wrap"><div class="quiz-header"><span>${run.exam?'Kỳ thi Chūnin':'Luyện nhẫn thuật'} · ${run.index+1}/${run.pool.length}</span><button class="secondary" data-exit>Tạm dừng</button></div><div class="progress" style="margin-bottom:20px"><i style="width:${run.index/run.pool.length*100}%"></i></div><section class="question"><small>Chương ${q.ch+1} · ${lessons.find(l=>l.id===q.lesson).title}</small><h2 style="margin-top:16px">${q.text}</h2><div class="options">${q.options.map((o,i)=>`<button class="option ${answered&&!run.exam?(i===q.correct?'correct':i===run.selected?'wrong':''):''}" data-answer="${i}" ${answered?'disabled':''}><span class="key">${i+1}</span>${o}${answered&&!run.exam&&i===q.correct?' ✓':''}</button>`).join('')}</div>${run.hints?`<div class="hints">${q.hints.slice(0,run.hints).map((h,i)=>`<div>Gợi ý ${i+1}: ${h}</div>`).join('')}</div>`:''}${answered?run.exam?'<div class="feedback">Đã ghi nhận lựa chọn. Đáp án sẽ có sau khi hoàn thành.</div>':`<div class="feedback" role="status"><h3 class="${run.selected===q.correct?'success':'error'}">${run.selected===q.correct?'Hoàn thành nhiệm vụ!':run.selected===-1?'Chưa biết cũng là điểm bắt đầu.':'Gần hơn một bước rồi.'}</h3><p><strong>Đáp án: ${q.options[q.correct]}.</strong> ${q.explain}</p>${workedHTML(q.worked)}${visualSlot(questions.find(x=>x.id===q.id),{key:run.id+':'+run.index,mode:run.selected===q.correct?'correct':run.selected===-1?'unknown':'wrong',selectedText:run.selected>=0?q.options[run.selected]:'',issue:run.selected>=0?q.distractorReasons?.[q.optionOrder[run.selected]]:null})}<div class="source">${src(q.ch,q.pages)}${extraRefs(q.supplementary)}</div></div>`:''}<div class="quiz-actions">${!answered?`<button class="secondary" data-answer="-1">Chưa biết</button>${!run.exam?`<button class="secondary" data-hint ${run.hints>=2?'disabled':''}>Gợi ý từng bước (${run.hints}/2)</button>`:''}`:`<span class="muted">${run.exam?'Đã lưu câu trả lời':'Tiến độ đã ghi nhận'}</span><button class="primary" data-next>${run.index===run.pool.length-1?'Xem kết quả':'Câu tiếp'}</button>`}</div></section><p class="muted" style="font-size:.8rem;text-align:center;margin-top:18px">1–4: chọn đáp án · Enter: tiếp tục sau khi trả lời</p></div>`}
function choose(i){if(!run||run.finished||run.selected!==null)return;let q=run.pool[run.index];run.selected=i;let ok=i===q.correct;run.answers.push({q,selected:i,ok});if(!run.exam){answer(state,q.id,ok);updateReview(state,q.id,ok?2:0,'mcq');run.id??='practice-'+Date.now();recordEvent(state,q,{id:run.id+':'+run.index,runId:run.id,quality:ok?2:0,format:'mcq',support:run.hints,novel:q.level>=3});save();beep(ok)}render()}
function next(){if(!run||run.selected===null)return;if(run.index<run.pool.length-1){run.index++;run.selected=null;run.hints=0}else{run.finished=true;if(run.exam){for(let a of run.answers){answer(state,a.q.id,a.ok);updateReview(state,a.q.id,a.ok?2:0,'mcq')}state.exams.push({date:new Date().toISOString(),score:Math.round(run.answers.filter(a=>a.ok).length/run.pool.length*100),kind:run.mode});save()}}render()}
function results(){let correct=run.answers.filter(a=>a.ok).length,score=Math.round(correct/run.pool.length*100);return `<div class="reading"><div class="eyebrow">Báo cáo nhiệm vụ</div><h1>${score>=80?'Một bước tiến vững vàng.':'Mỗi lần luyện, hiểu thêm một chút.'}</h1><div class="score">${score}%</div><p>${correct}/${run.pool.length} câu đúng · Cấp bậc hiện tại: <strong>${rank(state,lessons.length)}</strong>.</p><div class="actions"><button class="primary" data-reviewrun>Luyện lại câu chưa đúng</button><button class="secondary" data-go="home">Về bản đồ</button></div><div class="lesson-list" style="margin-top:28px">${run.answers.map(a=>`<div class="panel"><small class="${a.ok?'success':'error'}">${a.ok?'Đúng':'Cần ôn'}</small><h3>${a.q.text}</h3><p>Bạn chọn: ${a.selected<0?'Chưa biết':a.q.options[a.selected]}<br><strong>Đáp án: ${a.q.options[a.q.correct]}</strong></p><p>${a.q.explain}</p>${workedHTML(a.q.worked)}${visualSlot(questions.find(q=>q.id===a.q.id),{key:run.id+':result:'+a.q.id,mode:a.ok?'correct':a.selected<0?'unknown':'wrong',selectedText:a.selected>=0?a.q.options[a.selected]:''})}<div class="source">${src(a.q.ch,a.q.pages)}${extraRefs(a.q.supplementary)}</div></div>`).join('')}</div></div>`}
function beep(ok){if(!state.settings.sound)return;try{let ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=ok?660:270;g.gain.value=.035;o.start();o.stop(ctx.currentTime+.1);o.onended=()=>ctx.close()}catch{}}
function notebook(){let missed=wrong();return `<div class="eyebrow">Sổ nhẫn thuật · Tra nhanh, nhớ lâu</div><h1>Kiến thức luôn bên bạn.</h1><div class="filter"><button class="pill ${notebookMode==='formulas'?'active':''}" data-note="formulas">Công thức & thuật ngữ</button><button class="pill ${notebookMode==='wrong'?'active':''}" data-note="wrong">Hay trả lời sai (${missed.length})</button></div>${notebookMode==='wrong'?`<div class="actions"><button class="primary" data-start="wrong">Luyện lại câu sai</button></div><div class="notebook" style="margin-top:20px">${missed.length?missed.map(q=>`<div class="panel"><small>${state.records[q.id].attempts-state.records[q.id].correct} lần chưa đúng</small><h3>${q.text}</h3><p><strong>${q.options[q.correct]}</strong> · ${q.explain}</p><div class="source">${src(q.ch,q.pages)}</div></div>`).join(''):'<p class="empty">Sổ chưa có câu sai. Hãy bắt đầu một nhiệm vụ.</p>'}</div>`:`<div class="notebook">${lessons.map(l=>`<div class="panel"><small>Chương ${l.ch+1}</small><h3>${l.title}</h3><div class="formula">${l.memory}</div><details><summary>Đọc giải thích</summary><p>${l.body}</p></details><div class="source">${src(l.ch,l.pages)}</div></div>`).join('')}</div>`}`}
function sourcePage(){return `<div class="eyebrow">Nguồn kiến thức · Có thể đối chiếu</div><h1>Bốn cuộn thư nền tảng.</h1><p class="muted">Số trang trong website là số trang PDF, có thể khác số slide in trên bài giảng. Bản công khai không kèm PDF. Các chức năng học và mô phỏng vẫn dùng được. Chỉ bổ sung tài liệu tại máy nếu bạn có quyền sử dụng; xem hướng dẫn trong thư mục dist/sources.</p><div class="lesson-list">${sources.map((s,i)=>`<div class="lesson-row"><div><strong>Chương ${i+1}: ${chapters[i].topic}</strong><small>${sourceMeta[i].pages} trang PDF · ${s}</small></div><a href="sources/${s}" target="_blank" rel="noopener">Đọc PDF</a></div>`).join('')}</div><div class="panel" style="margin-top:24px"><h2>Cách dùng tài liệu</h2><p><a href="visual-audit.json" target="_blank" rel="noopener">Đối chiếu minh họa theo mã câu, chủ đề và trang nguồn</a></p><p>136 câu gốc (34/chương), 136 cách hỏi lại, 28 bài tương tự cố định và 36 biến thể số kiểm chứng. Câu chuyển thể từ bài tập được ghi nhãn riêng. Không tìm thấy đề thi thật trong thư mục; các kỳ thi trên website do website tự biên soạn.</p><p><a href="coverage.html" target="_blank" rel="noopener">Bảng đối chiếu từng phần tài liệu và phân loại nguồn</a></p><p>Bài học là phần diễn giải biên soạn từ 4 PDF; không thay thế toàn văn bài giảng. Chương 5 được nhắc trong đề cương nhưng chưa có tệp trong bộ tài liệu.</p><p>Ví dụ Naruto được ghi nhãn “Minh họa Naruto tự tạo”. Các phép so sánh giúp nhớ thuật ngữ; cơ chế mạng thực tế nằm ở phần giải thích chuyên môn.</p><p><a href="source-audit.json" target="_blank" rel="noopener">Bản đối chiếu nguồn: tên tệp, số trang, SHA-256 và bài tương ứng</a></p><h3>Nguồn bổ sung để làm rõ cơ chế</h3><p>Phần này do website biên soạn thêm, tách khỏi các PDF của môn học.</p><ul>${supplementarySources.map(r=>`<li><a href="${r.url}" target="_blank" rel="noopener">${r.title}</a></li>`).join('')}</ul><h3>Những chỗ cần đọc chính xác</h3><p>DNS cache tuân theo TTL, không có thời gian cố định cho mọi bản ghi. Checksum khớp chỉ là không phát hiện lỗi. IPv6 cấm phân mảnh tại router; nguồn có thể phân mảnh. TCP slow start tăng xấp xỉ gấp đôi mỗi RTT, không phải mỗi ACK. Dải /28 tăng theo bước 16; vài dải cuối trong slide chương 4 trang 35 bị ghi sai điểm kết thúc.</p></div>${footer()}`}
function settings(){return `<div class="reading"><div class="eyebrow">Cá nhân hóa buổi luyện</div><h1>Nhịp học của riêng bạn.</h1><div class="panel"><label class="setting"><span>Âm thanh phản hồi <small style="display:block;letter-spacing:0;text-transform:none">Mặc định tắt</small></span><input type="checkbox" data-setting="sound" ${state.settings.sound?'checked':''}></label><label class="setting"><span>Hiệu ứng hoàn thành ngắn <small style="display:block;letter-spacing:0;text-transform:none">Tôn trọng tùy chọn giảm chuyển động của thiết bị</small></span><input type="checkbox" data-setting="motion" ${state.settings.motion?'checked':''}></label><h3 style="margin-top:24px">Sao lưu tiến độ</h3><p>Tiến độ lưu bằng localStorage trên trình duyệt này, không tự đồng bộ giữa thiết bị. Xuất tệp để giữ bản sao hoặc chuyển sang máy khác. Nhập tệp hợp lệ sẽ thay tiến độ hiện tại.</p><div class="actions"><button class="secondary" data-export>Xuất tiến độ JSON</button><label class="secondary">Nhập tiến độ<input type="file" id="import" accept="application/json,.json" style="max-width:230px"></label></div></div><div class="panel" style="margin-top:20px"><h3>Điều kiện thăng cấp</h3><p>Học viên: bắt đầu.<br>Genin: hoàn thành ít nhất 20% bài và vững 3 chủ đề.<br>Chūnin: hoàn thành 50%, vững 8 chủ đề và đạt ít nhất 70% một bài thi.<br>Jōnin: hoàn thành 100%, vững 20 chủ đề và đạt ít nhất 80% một bài thi.<br>“Thành thạo” cần ít nhất 4 lần đúng độc lập qua 3 ngày và 2 lượt; có tự gõ đáp án và làm bài mới/vận dụng; chính xác gần đây ≥80% và lần tự làm gần nhất đúng. Tự đánh giá “Đã nhớ” và dùng gợi ý không tính là bằng chứng độc lập.</p></div></div>`}
const calcNames={subnet:'Chia mạng con',delay:'Độ trễ & pipeline',fragment:'Phân mảnh IPv4',checksum:'Internet checksum',routing:'Định tuyến Dijkstra'};
function field(label,id,val,type='number',extra=''){return `<label>${label}<input name="${id}" type="${type}" value="${val}" ${extra} required></label>`}
function calculatorBase(){let forms={subnet:field('Địa chỉ IPv4','ip','192.168.1.130','text')+field('Prefix hiện tại /p','prefix',24,'number','min="0" max="32"')+field('Số subnet bằng nhau cần có','subnets',4,'number','min="1" max="256"'),delay:field('Kích thước mỗi gói (byte)','bytes',1000)+field('Tốc độ mỗi liên kết (Mbps)','rate',1,'number','step="any"')+field('Độ dài mỗi liên kết (km)','km',100,'number','min="0" step="any"')+field('Tốc độ lan truyền (m/s)','speed',200000000)+field('Số liên kết','links',2)+field('Số gói liên tiếp','packets',3),fragment:field('Tổng chiều dài datagram (byte)','total',4000)+field('MTU (byte)','mtu',1500)+field('Header mỗi mảnh (byte)','header',20)+field('Identification','ident',422,'number','min="0" max="65535"'),checksum:field('Các từ 16 bit hệ hex, cách nhau bằng dấu cách','words','6660 5555 8F0C','text'),routing:field('Các cạnh vô hướng: u-v:2, u-x:1…','edges','u-v:2,u-x:1,u-w:5,v-w:3,v-x:2,x-w:3,x-y:1,w-y:1,w-z:5,y-z:2','text')+field('Nút nguồn','start','u','text')};return `<div class="eyebrow">Phòng luyện công thức · Có lời giải</div><h1>Tự tính. Hiểu từng bước.</h1><div class="filter">${Object.entries(calcNames).map(([id,n])=>`<button class="pill ${calc===id?'active':''}" data-calc="${id}">${n}</button>`).join('')}</div><section class="panel"><h2>${calcNames[calc]}</h2><form id="calc-form"><div class="fields">${forms[calc]}</div><button class="primary" type="submit">Giải từng bước</button></form><div id="calc-result" class="result" aria-live="polite"></div></section><p class="source">Nguồn: chương ${calc==='delay'?1:calc==='checksum'?3:4}. ${src(calc==='delay'?0:calc==='checksum'?2:3,calc==='delay'?[12,17]:calc==='checksum'?[19,22]:calc==='subnet'?[18,37]:calc==='fragment'?[44,48]:[65,79])}. Giả định được ghi trong lời giải.</p>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function solve(e){e.preventDefault();try{let fd=new FormData(e.target),output=solveCalc(calc,fd),spec=calcVisualSpec(calc,fd),q={id:'calculator-'+calc,ch:calc==='delay'?0:calc==='checksum'?2:3,pages:calc==='delay'?[16,17]:calc==='checksum'?[19,22]:calc==='fragment'?[47,48]:calc==='routing'?[68,79]:[18,37]};$('#calc-result').innerHTML=output+visualSlot(q,{spec,deep:true,mode:'correct',key:'calculator-'+calc+':'+JSON.stringify(spec.params).slice(0,100)});mountVisuals()}catch(err){$('#calc-result').innerHTML='<p class="error">'+esc(err.message)+'</p>'}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{selectedChapter=+b.dataset.ch;go('chapter')});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lessonId=b.dataset.lesson;go('lesson')});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=+b.dataset.filter;render()});document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{notebookMode=b.dataset.note;render()});document.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{calc=b.dataset.calc;render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>choose(+b.dataset.answer));if($('[data-next]'))$('[data-next]').onclick=next;if($('[data-hint]'))$('[data-hint]').onclick=()=>{run.hints++;render()};if($('[data-exit]'))$('[data-exit]').onclick=()=>{if(run.exam&&!confirm('Tạm dừng sẽ bỏ lượt thi chưa hoàn thành. Tiếp tục?'))return;go('practice')};if($('[data-reviewrun]'))$('[data-reviewrun]').onclick=()=>{let pool=run.answers.filter(a=>!a.ok).map(a=>a.q);if(!pool.length){toast('Bạn đã đúng toàn bộ!');return}run={mode:'review',exam:false,pool,index:0,selected:null,hints:0,answers:[],finished:false};render()};if($('[data-resume]'))$('[data-resume]').onclick=()=>{lessonId=(lessons.find(l=>!state.done.includes(l.id))||lessons[0]).id;go('lesson')};if($('[data-backchapter]'))$('[data-backchapter]').onclick=()=>{selectedChapter=lessons.find(l=>l.id===lessonId).ch;go('chapter')};if($('[data-complete]'))$('[data-complete]').onclick=()=>{if(!state.done.includes(lessonId))state.done.push(lessonId);save();start('lesson')};if($('[data-nextlesson]'))$('[data-nextlesson]').onclick=()=>{let i=lessons.findIndex(l=>l.id===lessonId);lessonId=lessons[(i+1)%lessons.length].id;render();window.scrollTo(0,0)};if($('#calc-form'))$('#calc-form').onsubmit=solve;document.querySelectorAll('[data-setting]').forEach(b=>b.onchange=()=>{state.settings[b.dataset.setting]=b.checked;save();document.body.classList.toggle('animate',state.settings.motion);render()});if($('[data-export]'))$('[data-export]').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='lang-la-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if($('#import'))$('#import').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('Tệp quá lớn (tối đa 2 MB).');let incoming=validate(JSON.parse(await file.text()));if(!confirm('Thay tiến độ hiện tại bằng bản sao này?'))return;state=incoming;save();render();toast('Đã khôi phục tiến độ.')}catch(err){toast('Không nhập được: '+err.message)}}}
document.addEventListener('keydown',e=>{cardUI.keyboard(e);examUI.keyboard(e);if(e.defaultPrevented)return;if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(run&&!run.finished){if(/^[1-4]$/.test(e.key)){e.preventDefault();choose(+e.key-1)}else if(e.key==='Enter'&&run.selected!==null&&e.target.tagName!=='BUTTON'){e.preventDefault();next()}}});
configureVisuals({getState:()=>state,save});
const cardUI=createCardUI({getState:()=>state,save,render,src,extraRefs,beep,notify:toast,open:()=>{view='cards';run=null;render();window.scrollTo(0,0)}});
const examUI=createExamUI({getState:()=>state,save,render,src,extraRefs});
if(state.cardSession&&!state.cardSession.finished)view='cards';
if(state.examSession&&!state.examSession.submitted){if(checkDeadline(state,state.examSession))save();view='exam';}
render();

function calculator(){let x=exercises[exerciseIndex],r=state.exerciseRecords[x.id];return calculatorBase()+`<section class="panel" style="margin-top:28px"><small>Nhiệm vụ tính toán · ${exerciseIndex+1}/${exercises.length}</small><h2>${x.title}</h2><p>${x.prompt}</p><details><summary>Dữ kiện và ký hiệu</summary><p><strong>Dữ kiện:</strong> ${esc(x.worked.given)}</p><p><strong>Ký hiệu:</strong> ${esc(x.worked.symbols)}</p></details><form id="exercise-form"><label>Đáp số (${x.unit})<input name="numeric" type="text" inputmode="decimal" autocomplete="off" required></label><p class="muted tolerance">${x.grading.integer?'Cần số nguyên chính xác.':`Sai số tuyệt đối cho phép ±${x.grading.absTol} ${x.unit}. Chấp nhận dấu phẩy hoặc dấu chấm thập phân.`}</p><div class="actions"><button class="primary" type="submit">Kiểm tra đáp số</button><button class="secondary" type="button" id="exercise-unknown">Chưa biết · xem lời giải</button></div></form><div id="exercise-feedback" aria-live="polite" style="margin-top:20px"></div><button class="secondary" id="exercise-next" style="margin-top:16px">Bài tính tiếp</button><p class="muted">${r?`Đã luyện ${r.attempts} lần, đúng ${r.correct} lần.`:'Chưa luyện bài này.'} Kết quả được lưu cùng tiến độ.</p><p class="source">${src(x.ch,x.pages)}</p></section>`}
function bindExercise(){let f=$('#exercise-form');if(!f)return;let x=exercises[exerciseIndex],submitted=false;function feedback(ok,unknown=false){if(submitted)return;submitted=true;let r=state.exerciseRecords[x.id]||{attempts:0,correct:0};state.exerciseRecords[x.id]={attempts:r.attempts+1,correct:r.correct+(ok?1:0),lastOK:ok};save();$('#exercise-feedback').innerHTML=`<h3 class="${ok?'success':'error'}">${ok?'Chính xác!':'Cùng xem từng bước.'}</h3>${workedHTML(x.worked)}${visualSlot(x,{key:'exercise:'+x.id,mode:ok?'correct':unknown?'unknown':'wrong',deep:true,answerText:x.answer+' '+x.unit})}`;mountVisuals();f.querySelector('button[type=submit]').disabled=true;$('#exercise-unknown').disabled=true;beep(ok)}f.onsubmit=e=>{e.preventDefault();let result=gradeNumeric(new FormData(f).get('numeric'),x.answer,x.grading);if(!result.valid){$('#exercise-feedback').textContent='Hãy nhập một số hữu hạn, ví dụ 0,0505. Không ghi đơn vị vào ô.';return}feedback(result.ok)};$('#exercise-unknown').onclick=()=>feedback(false,true);$('#exercise-next').onclick=()=>{exerciseIndex=(exerciseIndex+1)%exercises.length;render();$('#exercise-form').scrollIntoView?.({block:'center'})}}

function calcVisualSpec(kind,fd){let n=k=>Number(fd.get(k)),str=k=>String(fd.get(k)||'');if(kind==='delay')return {type:'delay',params:{bits:n('bytes')*8,rate:n('rate')*1e6,km:n('km'),speed:n('speed'),links:n('links'),packets:n('packets')}};if(kind==='subnet')return {type:'subnet',params:{ip:str('ip'),parent:n('prefix'),prefix:n('prefix')+Math.ceil(Math.log2(n('subnets')))}};if(kind==='fragment')return {type:'fragment',params:{total:n('total'),mtu:n('mtu'),header:n('header'),id:n('ident')}};if(kind==='checksum')return {type:'checksum',params:{words:str('words').trim().split(/\s+/).map(w=>parseInt(w,16)),bits:16}};let edges=str('edges').split(',').map(x=>{let m=x.trim().match(/^([a-zA-Z0-9]{1,12})-([a-zA-Z0-9]{1,12}):(\d+(?:\.\d+)?)$/);return [m[1],m[2],Number(m[3])]});return {type:'dijkstra',params:{edges,start:str('start'),target:edges.at(-1)[1]}}}
